export function solarManagementSign86(T,width=19){
 const shapes=[];for(const commands of SOLAR_OUTLINES86){const path=new T.ShapePath;for(const [op,...points] of commands){if(op==='M')path.moveTo(...points);else if(op==='L')path.lineTo(...points);else if(op==='Q')path.quadraticCurveTo(...points);else if(op==='C')path.bezierCurveTo(...points);else path.currentPath.closePath();}shapes.push(...path.toShapes(false));}
 const probe=new T.ExtrudeGeometry(shapes,{depth:1,bevelEnabled:false,curveSegments:6});probe.computeBoundingBox();const size=probe.boundingBox.getSize(new T.Vector3),scale=Math.min(width,32)/size.x;probe.dispose();
 const geometry=new T.ExtrudeGeometry(shapes,{depth:.16/scale,bevelEnabled:true,bevelThickness:.012/scale,bevelSize:.012/scale,bevelSegments:2,curveSegments:6,steps:1});geometry.scale(scale,scale,scale);geometry.computeBoundingBox();const box=geometry.boundingBox,center=box.getCenter(new T.Vector3);geometry.translate(-center.x,-center.y,.018-box.min.z);
 const letters=new T.Mesh(geometry,new T.MeshPhysicalMaterial({color:'#294952',metalness:.35,roughness:.38,clearcoat:.18}));letters.name='raised-persian-solar-management-name';letters.castShadow=letters.receiveShadow=true;
 const group=new T.Group;group.name='solar-management-metallic-sign';group.add(letters);const boardWidth=size.x*scale+1.2,boardHeight=size.y*scale+.9;
 const board=new T.Mesh(new T.BoxGeometry(boardWidth,boardHeight,.18),new T.MeshPhysicalMaterial({color:'#ded8cb',metalness:.18,roughness:.65}));board.position.z=-.1;board.name='metallic-solar-management-name-board';board.castShadow=board.receiveShadow=true;group.add(board);
 const frameMaterial=new T.MeshPhysicalMaterial({color:'#9ba9aa',metalness:.65,roughness:.38});for(const side of [-1,1]){const support=new T.Mesh(new T.BoxGeometry(.2,1.8,.24),frameMaterial);support.position.set(side*boardWidth*.3,-boardHeight/2-.9,-.12);const trim=new T.Mesh(new T.BoxGeometry(boardWidth,.09,.12),frameMaterial);trim.position.set(0,side*(boardHeight/2-.045),.015);support.castShadow=trim.castShadow=true;group.add(support,trim);}
 group.userData={text:'مدیریت نیروگاه خورشیدی',depth:.16,raised:true,metallic:true,plateHeight:boardHeight,editRoot:true,editLabel:'تابلو مدیریت نیروگاه خورشیدی',editId:'solar-management-name86'};return group;
}
